import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';import{Actions,Button,Card,Field,FormGrid,Message,Page,PageHeader,Status}from'../../spike/ui';import{Input}from'../../components/ui/input';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'بيانات المتجر',rank:5};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};const base=()=>String(__BACKEND_URL__||'http://localhost:9000').replace(/\/$/,'');export default function P(){const[f,setF]=useState<any>({owner_name:'',store_name:'',email:'',phone:'',city:'',address:'',governorate:'',logo_url:'',latitude:'',longitude:'',google_maps_url:''}),[pending,setPending]=useState<any>(null),[m,setM]=useState(''),[uploading,setUploading]=useState(false);const load=()=>api('/vendor/spike/store-profile').then(d=>{setF((x:any)=>({...x,...(d.profile||{}),store_name:d.profile?.store_name||d.seller?.name||'',email:d.profile?.email||d.seller?.email||''}));setPending(d.pending_update||null)});useEffect(()=>{load().catch(e=>setM(e.message))},[]);const uploadLogo=async(file?:File|null)=>{if(!file)return;setUploading(true);try{const fd=new FormData();fd.append('files',file);const r=await fetch(`${base()}/vendor/uploads`,{method:'POST',credentials:'include',body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'تعذر رفع الشعار');const url=d?.files?.[0]?.url||d?.uploads?.[0]?.url||d?.file?.url;if(!url)throw new Error('لم يرجع رابط الصورة');setF((x:any)=>({...x,logo_url:url}));setM('تم رفع الشعار')}catch(e:any){setM(e.message)}finally{setUploading(false)}};const save=async()=>{try{const d=await api('/vendor/spike/store-profile',{method:'POST',body:JSON.stringify(f)});setPending(d.pending_update);setM('تم إرسال تحديث بيانات المتجر للإدارة للمراجعة')}catch(e:any){setM(e.message)}};const statusTone=pending?.status==='approved'?'success':pending?.status==='rejected'?'danger':'warning';const statusText=pending?.status==='pending'?'يوجد تحديث قيد مراجعة الإدارة':pending?.status==='rejected'?`آخر تحديث مرفوض${pending.reason?`: ${pending.reason}`:''}`:pending?.status==='approved'?'تم اعتماد آخر تحديث':'';return <Page><Card><PageHeader title="بيانات المتجر" description="عدّل بيانات متجرك هنا. أي تعديل جديد يُرسل للإدارة للموافقة قبل تطبيقه."/>{statusText&&<Status tone={statusTone as any}>{statusText}</Status>}{m&&<Message>{m}</Message>}</Card><Card><FormGrid><Field label="اسم صاحب المتجر"><Input placeholder="اسم صاحب المتجر" value={f.owner_name} onChange={e=>setF({...f,owner_name:e.target.value})}/></Field><Field label="اسم المتجر"><Input placeholder="اسم المتجر" value={f.store_name} onChange={e=>setF({...f,store_name:e.target.value})}/></Field><Field label="البريد الإلكتروني"><Input type="email" placeholder="example@email.com" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></Field><Field label="رقم الهاتف"><Input placeholder="رقم الهاتف" value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/></Field><Field label="المدينة"><Input placeholder="المدينة" value={f.city} onChange={e=>setF({...f,city:e.target.value})}/></Field><Field label="المحافظة"><Input placeholder="المحافظة" value={f.governorate} onChange={e=>setF({...f,governorate:e.target.value})}/></Field><Field label="العنوان" wide><Input placeholder="العنوان الكامل" value={f.address} onChange={e=>setF({...f,address:e.target.value})}/></Field><Field label="شعار المتجر" wide><Input type="file" accept="image/*" disabled={uploading} onChange={e=>void uploadLogo(e.target.files?.[0])}/>{f.logo_url&&<div className="spike-upload-preview"><img src={f.logo_url} alt="شعار المتجر"/></div>}</Field><Field label="رابط Google Maps" wide><Input placeholder="https://maps.google.com/..." value={f.google_maps_url} onChange={e=>setF({...f,google_maps_url:e.target.value})}/></Field><Field label="Latitude" hint="اختياري"><Input type="number" step="any" placeholder="مثال: 15.3694" value={f.latitude??''} onChange={e=>setF({...f,latitude:e.target.value})}/></Field><Field label="Longitude" hint="اختياري"><Input type="number" step="any" placeholder="مثال: 44.1910" value={f.longitude??''} onChange={e=>setF({...f,longitude:e.target.value})}/></Field></FormGrid><Actions><Button disabled={uploading} onClick={save}>{uploading?'جاري رفع الصورة...':'إرسال التحديث للمراجعة'}</Button></Actions></Card></Page>}
